46	/****************************************************************************
47	 * Name: libelf_loadhdrs
48	 *
49	 * Description:
50	 *   Loads program and section headers into memory.
51	 *
52	 * Returned Value:
53	 *   0 (OK) is returned on success and a negated errno is returned on
54	 *   failure.
55	 *
56	 ****************************************************************************/
57	
58	int libelf_loadhdrs(FAR struct mod_loadinfo_s *loadinfo)
59	{
60	  size_t shdrsize;
61	  size_t phdrsize;
62	  int ret;
63	
64	  DEBUGASSERT(loadinfo->shdr == NULL);
65	  DEBUGASSERT(loadinfo->phdr == NULL);
66	
67	  /* Verify that there are sections */
68	
69	  if (loadinfo->ehdr.e_shnum < 1)
70	    {
71	      berr("ERROR: No sections(?)\n");
72	      return -EINVAL;
73	    }
74	
75	  /* Get the total size of the section header table */
76	
77	  shdrsize = (size_t)loadinfo->ehdr.e_shentsize *
78	             (size_t)loadinfo->ehdr.e_shnum;
79	  if (loadinfo->ehdr.e_shoff + shdrsize > loadinfo->filelen)
80	    {
81	      berr("ERROR: Insufficient space in file for section header table\n");
82	      return -ESPIPE;
83	    }
84	
85	  /* Allocate memory to hold a working copy of the sector header table */
86	
87	  loadinfo->shdr = (FAR Elf_Shdr *)lib_malloc(shdrsize);
88	  if (!loadinfo->shdr)
89	    {
90	      berr("ERROR: Failed to allocate the section header table. Size: %zu\n",
91	           shdrsize);
92	      return -ENOMEM;
93	    }
94	
95	  /* Read the section header table into memory */
96	
97	  ret = libelf_read(loadinfo, (FAR uint8_t *)loadinfo->shdr, shdrsize,
98	                    loadinfo->ehdr.e_shoff);
99	  if (ret < 0)
100	    {
101	      berr("ERROR: Failed to read section header table: %d\n", ret);
102	    }
103	
104	  if (loadinfo->ehdr.e_phnum > 0)
105	    {
106	      /* Get the total size of the program header table */
107	
108	      phdrsize = (size_t)loadinfo->ehdr.e_phentsize *
109	                 (size_t)loadinfo->ehdr.e_phnum;
110	      if (loadinfo->ehdr.e_phoff + phdrsize > loadinfo->filelen)
111	        {
112	          berr("ERROR: Insufficent space for program header table\n");
113	          return -ESPIPE;
114	        }
115	
116	      /* Allocate memory to hold a working copy of the program header table */
117	
118	      loadinfo->phdr = (FAR Elf_Phdr *)lib_malloc(phdrsize);
119	      if (!loadinfo->phdr)
120	        {
121	          berr("ERROR: Failed to allocate the program header table."
122	               "Size: %zu\n", phdrsize);
123	          return -ENOMEM;
124	        }
125	
126	      /* Read the program header table into memory */
127	
128	      ret = libelf_read(loadinfo, (FAR uint8_t *)loadinfo->phdr, phdrsize,
129	                        loadinfo->ehdr.e_phoff);
130	      if (ret < 0)
131	        {
132	          berr("ERROR: Failed to read program header table: %d\n", ret);
133	        }
134	    }
135	  else
136	    {
137	      loadinfo->phdr = NULL;
138	    }
139	
140	  return ret;
141	}
