94	/****************************************************************************
95	 * Name: elf_uart_puts / elf_uart_puthex / elf_uart_putdec
96	 *
97	 * Description:
98	 *   Low-level UART debug helpers for this board (UART0 base 0x04140000).
99	 *   Used when serial driver is not yet available during ELF loading.
100	 *
101	 ****************************************************************************/
102	
103	static void elf_uart_putc(char c)
104	{
105	  volatile uint8_t *u = (volatile uint8_t *)0x04140000;
106	  while ((*(volatile uint32_t *)(0x04140014) & 0x20) == 0);
107	  *u = c;
108	}
109	
110	static void elf_uart_puts(FAR const char *s)
111	{
112	  while (*s) elf_uart_putc(*s++);
113	}
114	
115	static void elf_uart_puthex(unsigned long v)
116	{
117	  int i, started = 0;
118	  for (i = (sizeof(v) * 2) - 1; i >= 0; i--)
119	    {
120	      char c = "0123456789abcdef"[(v >> (i * 4)) & 0xf];
121	      if (c != '0' || started || i == 0)
122	        {
123	          started = 1;
124	          elf_uart_putc(c);
125	        }
126	    }
127	}
128	
129	static void elf_uart_putdec(int v)
130	{
131	  char buf[12];
132	  int i = 0, neg = 0;
133	  if (v < 0) { neg = 1; v = -v; }
134	  if (v == 0) buf[i++] = '0';
135	  else { while (v) { buf[i++] = '0' + (v % 10); v /= 10; } }
136	  if (neg) buf[i++] = '-';
137	  while (i) elf_uart_putc(buf[--i]);
138	}
