140	/****************************************************************************
141	 * Name: elf_loadbinary
142	 *
143	 * Description:
144	 *   Verify that the file is an ELF binary and, if so, load the ELF
145	 *   binary into memory
146	 *
147	 ****************************************************************************/
148	
149	static int elf_loadbinary(FAR struct binary_s *binp,
150	                          FAR const char *filename,
151	                          FAR const struct symtab_s *exports,
152	                          int nexports)
153	{
154	  struct mod_loadinfo_s loadinfo;
155	  Elf_Sym sym;
156	  int ret;
157	
158	  binfo("Loading file: %s\n", filename);
159	
160	  /* DBG: print key context */
161	  elf_uart_puts("\n[ELF] load: ");
162	  elf_uart_puts(filename);
163	  elf_uart_puts(" exports=0x");
164	  elf_uart_puthex((unsigned long)exports);
165	  elf_uart_puts(" nexports=");
166	  elf_uart_putdec(nexports);
167	  elf_uart_putc('\n');
168	
169	  /* Initialize the ELF library to load the program binary. */
170	
171	  ret = libelf_initialize(filename, &loadinfo);
172	  libelf_dumploadinfo(&loadinfo);
173	  if (ret != 0)
174	    {
175	      berr("ELF_LOAD: libelf_initialize failed: ret=%d\n", ret);
176	      elf_uart_puts("[ELF] INIT_FAIL ret=");
177	      elf_uart_putdec(ret);
178	      elf_uart_putc('\n');
179	      goto errout_with_init;
180	    }
181	
182	  /* DBG: print ELF identity */
183	  elf_uart_puts("[ELF] header: type=");
184	  elf_uart_putdec(loadinfo.ehdr.e_type);
185	  elf_uart_puts(" (1=REL 2=EXEC 3=DYN) machine=");
186	  elf_uart_putdec(loadinfo.ehdr.e_machine);
187	  elf_uart_puts(" entry=0x");
188	  elf_uart_puthex(loadinfo.ehdr.e_entry);
189	  elf_uart_puts(" shnum=");
190	  elf_uart_putdec(loadinfo.ehdr.e_shnum);
191	  elf_uart_putc('\n');
192	
193	  /* Load the program binary */
194	
195	  /* DBG: before load */
196	  elf_uart_puts("[ELF] textalloc=0x");
197	  elf_uart_puthex(loadinfo.textalloc);
198	  elf_uart_puts(" textsize=0x");
199	  elf_uart_puthex(loadinfo.textsize);
200	  elf_uart_puts(" datastart=0x");
201	  elf_uart_puthex(loadinfo.datastart);
202	  elf_uart_puts(" datasize=0x");
203	  elf_uart_puthex(loadinfo.datasize);
204	  elf_uart_putc('\n');
205	
206	  ret = libelf_load_with_addrenv(&loadinfo, false);
207	  libelf_dumploadinfo(&loadinfo);
208	  if (ret != 0)
209	    {
210	      berr("Failed to load ELF program binary: %d\n", ret);
211	      elf_uart_puts("[ELF] LOAD_FAIL ret=");
212	      elf_uart_putdec(ret);
213	      elf_uart_putc('\n');
214	      goto errout_with_init;
215	    }
216	
217	  elf_uart_puts("[ELF] LOAD_OK textalloc=0x");
218	  elf_uart_puthex(loadinfo.textalloc);
219	  elf_uart_puts(" datastart=0x");
220	  elf_uart_puthex(loadinfo.datastart);
221	  elf_uart_putc('\n');
222	
223	  /* Bind the program to the exported symbol table */
224	
225	#ifdef CONFIG_LIBC_ELF_GOT
226	  elf_uart_puts("[ELF] gotindex=");
227	  elf_uart_putdec(loadinfo.gotindex);
228	  elf_uart_putc('\n');
229	#endif
230	
231	  if (loadinfo.ehdr.e_type == ET_REL
232	#ifdef CONFIG_LIBC_ELF_GOT
233	      || loadinfo.gotindex >= 0
234	#endif
235	     )
236	    {
237	      elf_uart_puts("[ELF] need BIND (ET_REL or has GOT), calling libelf_bind\n");
238	      ret = libelf_bind(&binp->mod, &loadinfo, exports, nexports);
239	      if (ret != 0)
240	        {
241	          berr("Failed to bind symbols program binary: %d\n", ret);
242	          elf_uart_puts("[ELF] BIND_FAIL ret=");
243	          elf_uart_putdec(ret);
244	          elf_uart_puts(" (22=EINVAL 2=ENOENT 12=ENOMEM 8=ENOEXEC)\n");
245	          goto errout_with_load;
246	        }
247	
248	      elf_uart_puts("[ELF] BIND_OK entry=0x");
249	      elf_uart_puthex(loadinfo.textalloc + loadinfo.ehdr.e_entry);
250	      elf_uart_putc('\n');
251	
252	      binp->entrypt = (main_t)(loadinfo.textalloc + loadinfo.ehdr.e_entry);
253	    }
254	  else if (loadinfo.ehdr.e_type == ET_EXEC)
255	    {
256	      elf_uart_puts("[ELF] ET_EXEC: skip bind, entry=0x");
257	      elf_uart_puthex(loadinfo.ehdr.e_entry);
258	      elf_uart_putc('\n');
259	
260	      if (nexports > 0)
261	        {
262	          berr("Cannot bind exported symbols to a "
263	               "fully linked executable\n");
264	          ret = -ENOEXEC;
265	          goto errout_with_load;
266	        }
267	
268	      /* The entrypoint for a fully linked executable can be found directly */
269	
270	      binp->entrypt = (main_t)(loadinfo.ehdr.e_entry);
271	    }
272	
273	  else
274	    {
275	      berr("Unexpected elf type %d\n", loadinfo.ehdr.e_type);
276	      elf_uart_puts("[ELF] BAD_TYPE type=");
277	      elf_uart_putdec(loadinfo.ehdr.e_type);
278	      elf_uart_putc('\n');
279	      ret = -ENOEXEC;
280	      goto errout_with_load;
281	    }
282	
283	  /* Return the load information */
284	
285	  ret = libelf_findsymbol(&loadinfo, "nx_stacksize", &sym);
286	  if (ret == 0)
287	    {
288	      binp->stacksize = sym.st_value;
289	    }
290	  else
291	    {
292	      binp->stacksize = CONFIG_ELF_STACKSIZE;
293	    }
294	
295	  ret = libelf_findsymbol(&loadinfo, "nx_priority", &sym);
296	  if (ret == 0)
297	    {
298	      binp->priority = sym.st_value;
299	    }
300	  else
301	    {
302	      binp->priority = SCHED_PRIORITY_DEFAULT;
303	    }
304	
305	#ifdef CONFIG_SCHED_USER_IDENTITY
306	  ret = libelf_findsymbol(&loadinfo, "nx_uid", &sym);
307	  if (ret == 0)
308	    {
309	      binp->uid = sym.st_value;
310	    }
311	  else
312	    {
313	      binp->uid = 0;
314	    }
315	
316	  ret = libelf_findsymbol(&loadinfo, "nx_gid", &sym);
317	  if (ret == 0)
318	    {
319	      binp->gid = sym.st_value;
320	    }
321	  else
322	    {
323	      binp->gid = 0;
324	    }
325	
326	  ret = libelf_findsymbol(&loadinfo, "nx_mode", &sym);
327	  if (ret == 0)
328	    {
329	      binp->mode = sym.st_value;
330	    }
331	  else
332	    {
333	      binp->mode = 0;
334	    }
335	#endif
336	
337	#ifdef CONFIG_MM_TASK_HEAP
338	  ret = libelf_findsymbol(&loadinfo, "nx_heapsize", &sym);
339	  if (ret == 0)
340	    {
341	      binp->heapsize = sym.st_value;
342	    }
343	  else
344	    {
345	      binp->priority = CONFIG_MM_TASK_HEAP_DEFAULT_SIZE;
346	    }
347	#endif
348	
349	  /* Add the ELF allocation to the alloc[] only if there is no address
350	   * environment.  If there is an address environment, it will automatically
351	   * be freed when the function exits
352	   *
353	   * REVISIT:  If the module is loaded then unloaded, wouldn't this cause
354	   * a memory leak?
355	   */
356	
357	#ifdef CONFIG_ARCH_ADDRENV
358	  /* Save the address environment in the binfmt structure.  This will be
359	   * needed when the module is executed.
360	   */
361	
362	  binp->addrenv = loadinfo.addrenv;
363	
364	#else
365	#  ifdef CONFIG_ARCH_USE_SEPARATED_SECTION
366	  if (loadinfo.ehdr.e_type == ET_REL)
367	    {
368	      binp->mod.sectalloc = (FAR void *)loadinfo.sectalloc;
369	      binp->mod.nsect     = loadinfo.ehdr.e_shnum;
370	    }
371	#  endif
372	
373	  binp->mod.textalloc = (FAR void *)loadinfo.textalloc;
374	  binp->mod.dataalloc = (FAR void *)loadinfo.datastart;
375	#  ifdef CONFIG_BINFMT_CONSTRUCTORS
376	  binp->mod.initarr = loadinfo.initarr;
377	  binp->mod.finiarr = loadinfo.finiarr;
378	#  endif
379	#endif
380	
381	#ifdef CONFIG_BINFMT_CONSTRUCTORS
382	  /* Save information about constructors and destructors. */
383	
384	  binp->mod.initarr = loadinfo.initarr;
385	  binp->mod.ninit   = loadinfo.ninit;
386	
387	  binp->mod.finiarr = loadinfo.finiarr;
388	  binp->mod.nfini   = loadinfo.nfini;
389	#endif
390	
391	#ifdef CONFIG_SCHED_USER_IDENTITY
392	  /* Save IDs and mode from file system */
393	
394	  binp->uid  = loadinfo.fileuid;
395	  binp->gid  = loadinfo.filegid;
396	  binp->mode = loadinfo.filemode;
397	#endif
398	
399	  libelf_dumpentrypt(&loadinfo);
400	#if defined(CONFIG_PIC) && defined(CONFIG_LIBC_ELF_GOT)
401	  if (loadinfo.gotindex >= 0)
402	    {
403	      FAR struct dspace_s *dspaces = kmm_zalloc(sizeof(struct dspace_s));
404	
405	      if (dspaces == NULL)
406	        {
407	          ret = -ENOMEM;
408	          goto errout_with_load;
409	        }
410	
411	      dspaces->region = (FAR void *)loadinfo.shdr[loadinfo.gotindex].sh_addr;
412	      dspaces->crefs = 1;
413	      binp->picbase = (FAR void *)dspaces;
414	    }
415	#endif
416	
417	#ifdef HAVE_LIBC_ELF_NAMES
418	  /* Save the filename in the registry entry */
419	
420	  strlcpy(binp->mod.modname, strrchr(filename, '/') == NULL ?
421	          filename: strrchr(filename, '/') + 1,
422	          sizeof(binp->mod.modname));
423	#endif
424	
425	  libelf_uninitialize(&loadinfo);
426	  return OK;
427	
428	errout_with_load:
429	  libelf_unload(&loadinfo);
430	errout_with_init:
431	  libelf_uninitialize(&loadinfo);
432	  return ret;
433	}
