72	#ifdef CONFIG_ARCH_USE_SEPARATED_SECTION
73	static int libelf_section_alloc(FAR struct mod_loadinfo_s *loadinfo,
74	                                FAR Elf_Shdr *shdr, uint8_t idx)
75	{
76	  if (loadinfo->ehdr.e_type == ET_DYN)
77	    {
78	      return -EINVAL;
79	    }
80	
81	  if (loadinfo->sectalloc == NULL)
82	    {
83	      /* Allocate memory info for all sections */
84	
85	      loadinfo->sectalloc = lib_zalloc(sizeof(uintptr_t) *
86	                                       loadinfo->ehdr.e_shnum);
87	      if (loadinfo->sectalloc == NULL)
88	        {
89	          return -ENOMEM;
90	        }
91	    }
92	
93	  libelf_sectname(loadinfo, shdr);
94	  if ((shdr->sh_flags & SHF_WRITE) != 0)
95	    {
96	#  ifdef CONFIG_ARCH_USE_DATA_HEAP
97	      loadinfo->sectalloc[idx] = (uintptr_t)
98	                                 up_dataheap_memalign(
99	                                   (FAR const char *)loadinfo->iobuffer,
100	                                                     shdr->sh_addralign,
101	                                                     shdr->sh_size);
102	#  else
103	      loadinfo->sectalloc[idx] = (uintptr_t)lib_memalign(shdr->sh_addralign,
104	                                                        shdr->sh_size);
105	#  endif
106	
107	      if (loadinfo->datastart == 0)
108	        {
109	          loadinfo->datastart = loadinfo->sectalloc[idx];
110	        }
111	    }
112	#  ifdef CONFIG_LIBC_ELF_GOT
113	  else if (loadinfo->xipbase != 0)
114	    {
115	      loadinfo->sectalloc[idx] = loadinfo->xipbase + shdr->sh_offset;
116	      if (loadinfo->textalloc == 0)
117	        {
118	          loadinfo->textalloc = loadinfo->sectalloc[idx];
119	        }
120	    }
121	#  endif
122	  else
123	    {
124	#  ifdef CONFIG_ARCH_USE_TEXT_HEAP
125	      loadinfo->sectalloc[idx] = (uintptr_t)
126	                                 up_textheap_memalign(
127	                                   (FAR const char *)loadinfo->iobuffer,
128	                                                     shdr->sh_addralign,
129	                                                     shdr->sh_size);
130	#  else
131	      loadinfo->sectalloc[idx] = (uintptr_t)
132	                                  lib_memalign(shdr->sh_addralign,
133	                                               shdr->sh_size);
134	#  endif
135	
136	      if (loadinfo->textalloc == 0)
137	        {
138	          loadinfo->textalloc = loadinfo->sectalloc[idx];
139	        }
140	    }
141	
142	  return OK;
143	}
144	#endif
