146	/****************************************************************************
147	 * Name: libelf_elfsize
148	 *
149	 * Description:
150	 *   Calculate total memory allocation for the ELF file.
151	 *
152	 ****************************************************************************/
153	
154	static void libelf_elfsize(FAR struct mod_loadinfo_s *loadinfo, bool alloc)
155	{
156	  size_t textsize = 0;
157	  size_t datasize = 0;
158	  int i;
159	
160	  /* Accumulate the size each section into memory that is marked SHF_ALLOC
161	   * if CONFIG_ARCH_USE_SEPARATED_SECTION is enabled, allocate
162	   * (and zero) memory for the each section.
163	   */
164	
165	  if (loadinfo->ehdr.e_type == ET_DYN)
166	    {
167	      for (i = 0; i < loadinfo->ehdr.e_phnum; i++)
168	        {
169	          FAR Elf_Phdr *phdr = &loadinfo->phdr[i];
170	          FAR void *textaddr = NULL;
171	
172	          if (phdr->p_type == PT_LOAD)
173	            {
174	              if (phdr->p_flags & PF_X)
175	                {
176	                  textsize += phdr->p_memsz;
177	                  textaddr = (FAR void *)(uintptr_t)phdr->p_vaddr;
178	                }
179	              else
180	                {
181	                  datasize += phdr->p_memsz;
182	                  loadinfo->datasec = phdr->p_vaddr;
183	                  loadinfo->segpad  = phdr->p_vaddr -
184	                                      ((uintptr_t)textaddr + textsize);
185	                }
186	            }
187	        }
188	    }
189	  else
190	    {
191	      for (i = 0; i < loadinfo->ehdr.e_shnum; i++)
192	        {
193	          FAR Elf_Shdr *shdr = &loadinfo->shdr[i];
194	
195	          /* SHF_ALLOC indicates that the section requires memory during
196	           * execution.
197	           */
198	
199	          if ((shdr->sh_flags & SHF_ALLOC) != 0)
200	            {
201	              /* SHF_WRITE indicates that the section address space is write-
202	               * able
203	               */
204	
205	              if ((shdr->sh_flags & SHF_WRITE) != 0
206	#ifdef CONFIG_ARCH_HAVE_TEXT_HEAP_WORD_ALIGNED_READ
207	                  || (shdr->sh_flags & SHF_EXECINSTR) == 0
208	#endif
209	                  )
210	                {
211	#ifdef CONFIG_ARCH_USE_SEPARATED_SECTION
212	                  if (alloc && libelf_section_alloc(loadinfo, shdr, i) >= 0)
213	                    {
214	                      continue;
215	                    }
216	#endif
217	
218	                  datasize = _ALIGN_UP(datasize, shdr->sh_addralign);
219	                  datasize += ELF_ALIGNUP(shdr->sh_size);
220	                  if (loadinfo->dataalign < shdr->sh_addralign)
221	                    {
222	                      loadinfo->dataalign = shdr->sh_addralign;
223	                    }
224	                }
225	              else
226	                {
227	#ifdef CONFIG_ARCH_USE_SEPARATED_SECTION
228	                  if (alloc && libelf_section_alloc(loadinfo, shdr, i) >= 0)
229	                    {
230	                      continue;
231	                    }
232	#endif
233	
234	                  textsize = _ALIGN_UP(textsize, shdr->sh_addralign);
235	                  textsize += ELF_ALIGNUP(shdr->sh_size);
236	                  if (loadinfo->textalign < shdr->sh_addralign)
237	                    {
238	                      loadinfo->textalign = shdr->sh_addralign;
239	                    }
240	                }
241	            }
242	        }
243	    }
244	
245	  /* Save the allocation size */
246	
247	  loadinfo->textsize = textsize;
248	  loadinfo->datasize = datasize;
249	}
