251	/****************************************************************************
252	 * Name: libelf_vma2lma
253	 *
254	 * Description:
255	 *   Convert section`s VMA to LMA according to PhysAddr(p_paddr) of
256	 *   Program Header.
257	 *
258	 * Returned Value:
259	 *   0 (OK) is returned on success and a negated errno is returned on
260	 *   failure.
261	 *
262	 ****************************************************************************/
263	
264	static int libelf_vma2lma(FAR struct mod_loadinfo_s *loadinfo,
265	                          FAR Elf_Shdr *shdr, FAR Elf_Addr *lma)
266	{
267	  int i;
268	
269	  for (i = 0; i < loadinfo->ehdr.e_phnum; i++)
270	    {
271	      FAR Elf_Phdr *phdr = &loadinfo->phdr[i];
272	
273	      if (shdr->sh_addr >= phdr->p_vaddr &&
274	          shdr->sh_addr + shdr->sh_size <= phdr->p_vaddr + phdr->p_memsz &&
275	          shdr->sh_offset >= phdr->p_offset &&
276	          shdr->sh_offset <= phdr->p_offset + phdr->p_filesz)
277	        {
278	          *lma = phdr->p_paddr + shdr->sh_addr - phdr->p_vaddr;
279	          return OK;
280	        }
281	    }
282	
283	  return -ENOENT;
284	}
