286	/****************************************************************************
287	 * Name: libelf_set_emptysect_vma
288	 *
289	 * Description:
290	 *   Set VMA for empty and unallocated sections, some relocations might
291	 *   depend on this.
292	 *
293	 * Returned Value:
294	 *   None.
295	 *
296	 ****************************************************************************/
297	
298	static void libelf_set_emptysect_vma(FAR struct mod_loadinfo_s *loadinfo,
299	                                     int section)
300	{
301	  FAR Elf_Shdr *shdr = &loadinfo->shdr[section];
302	
303	  /* Set the section as data or text, depending on SHF_WRITE */
304	
305	  if ((shdr->sh_flags & SHF_WRITE) != 0
306	#ifdef CONFIG_ARCH_HAVE_TEXT_HEAP_WORD_ALIGNED_READ
307	      || (shdr->sh_flags & SHF_EXECINSTR) == 0
308	#endif
309	      )
310	    {
311	      shdr->sh_addr = loadinfo->datastart;
312	    }
313	  else
314	    {
315	      shdr->sh_addr = loadinfo->textalloc;
316	    }
317	}
