319	/****************************************************************************
320	 * Name: libelf_loadfile
321	 *
322	 * Description:
323	 *   Read the section data into memory. Section addresses in the shdr[] are
324	 *   updated to point to the corresponding position in the memory.
325	 *
326	 * Returned Value:
327	 *   0 (OK) is returned on success and a negated errno is returned on
328	 *   failure.
329	 *
330	 ****************************************************************************/
331	
332	static inline int libelf_loadfile(FAR struct mod_loadinfo_s *loadinfo,
333	                                  bool is_vma)
334	{
335	  FAR uint8_t *text = (FAR uint8_t *)loadinfo->textalloc;
336	  FAR uint8_t *data = (FAR uint8_t *)loadinfo->datastart;
337	  int ret;
338	  int i;
339	
340	  /* Read each PT_LOAD area into memory */
341	
342	  binfo("Loading sections - text: %p.%zx data: %p.%zx\n",
343	        text, loadinfo->textsize, data, loadinfo->datasize);
344	
345	  if (loadinfo->ehdr.e_type == ET_DYN)
346	    {
347	      for (i = 0; i < loadinfo->ehdr.e_phnum; i++)
348	        {
349	          FAR Elf_Phdr *phdr = &loadinfo->phdr[i];
350	
351	          if (phdr->p_type == PT_LOAD)
352	            {
353	              if (phdr->p_flags & PF_X)
354	                {
355	                  ret = libelf_read(loadinfo, buffer_data_address(text),
356	                                    phdr->p_filesz,
357	                                    phdr->p_offset);
358	                }
359	              else
360	                {
361	                  size_t bsssize = phdr->p_memsz - phdr->p_filesz;
362	                  ret = libelf_read(loadinfo, data, phdr->p_filesz,
363	                                    phdr->p_offset);
364	                  memset(data + phdr->p_filesz, 0, bsssize);
365	                }
366	
367	              if (ret < 0)
368	                {
369	                  berr("ERROR: Failed to read section %d: %d\n", i, ret);
370	                  return ret;
371	                }
372	            }
373	        }
374	    }
375	  else
376	    {
377	      for (i = 0; i < loadinfo->ehdr.e_shnum; i++)
378	        {
379	          FAR Elf_Shdr *shdr = &loadinfo->shdr[i];
380	          FAR uint8_t **pptr = NULL;
381	
382	          /* SHF_ALLOC indicates that the section requires memory during
383	           * execution
384	           */
385	
386	          if ((shdr->sh_flags & SHF_ALLOC) == 0 || shdr->sh_size == 0)
387	            {
388	              /* Set the VMA regardless */
389	
390	              libelf_set_emptysect_vma(loadinfo, i);
391	              continue;
392	            }
393	
394	#ifdef CONFIG_ARCH_USE_SEPARATED_SECTION
395	          if (loadinfo->ehdr.e_type == ET_REL ||
396	              loadinfo->ehdr.e_type == ET_EXEC)
397	            {
398	              pptr = (FAR uint8_t **)&loadinfo->sectalloc[i];
399	            }
400	#endif
401	
402	          if (pptr == NULL)
403	            {
404	              /* SHF_WRITE indicates that the section address space is
405	               * writeable
406	               */
407	
408	              if ((shdr->sh_flags & SHF_WRITE) != 0
409	#ifdef CONFIG_ARCH_HAVE_TEXT_HEAP_WORD_ALIGNED_READ
410	                  || (shdr->sh_flags & SHF_EXECINSTR) == 0
411	#endif
412	                  )
413	                {
414	                  pptr = &data;
415	                }
416	              else
417	                {
418	                  pptr = &text;
419	                }
420	
421	#ifdef CONFIG_LIBC_ELF_GOT
422	              if (loadinfo->xipbase == 0)
423	#endif
424	                {
425	                  /* If xipbase is not set, align the address
426	                   * xipbase is set, the address can't be aligned
427	                   */
428	
429	                  *pptr = (FAR uint8_t *)_ALIGN_UP((uintptr_t)*pptr,
430	                                                   shdr->sh_addralign);
431	                }
432	            }
433	
434	#ifdef CONFIG_LIBC_ELF_GOT
435	          if ((shdr->sh_flags & SHF_WRITE) == 0 && loadinfo->xipbase != 0)
436	            {
437	              goto skipload;
438	            }
439	#endif
440	
441	          /* SHT_NOBITS indicates that there is no data in the file for the
442	           * section.
443	           */
444	
445	          if (shdr->sh_type != SHT_NOBITS)
446	            {
447	              if (is_vma)
448	                {
449	                  ret = libelf_vma2lma(loadinfo, shdr, (FAR Elf_Addr *)pptr);
450	                  if (ret < 0)
451	                    {
452	                      berr("ERROR: Failed to convert addr %d: %d\n", i, ret);
453	                      return ret;
454	                    }
455	                }
456	
457	              /* Read the section data from sh_offset to the memory region */
458	
459	              ret = libelf_read(loadinfo, buffer_data_address(*pptr),
460	                                shdr->sh_size, shdr->sh_offset);
461	              if (ret < 0)
462	                {
463	                  berr("ERROR: Failed to read section %d: %d\n", i, ret);
464	                  return ret;
465	                }
466	            }
467	
468	          /* If there is no data in an allocated section, then the allocated
469	           * section must be cleared.
470	           */
471	
472	          else if (*pptr != NULL)
473	            {
474	              if (!is_vma)
475	                {
476	                  memset(*pptr, 0, shdr->sh_size);
477	                }
478	            }
479	
480	#ifdef CONFIG_LIBC_ELF_GOT
481	skipload:
482	#endif
483	          /* Update sh_addr to point to copy in memory */
484	
485	          binfo("%d. %08lx->%08lx\n", i,
486	                (unsigned long)shdr->sh_addr, (unsigned long)*pptr);
487	
488	          /* Use offset to remember the original file address */
489	
490	          shdr->sh_offset = (uintptr_t)shdr->sh_addr;
491	          shdr->sh_addr = (uintptr_t)*pptr;
492	
493	#ifdef CONFIG_ARCH_USE_SEPARATED_SECTION
494	          if (loadinfo->ehdr.e_type != ET_REL)
495	            {
496	              *pptr += ELF_ALIGNUP(shdr->sh_size);
497	            }
498	#else
499	          /* Setup the memory pointer for the next time through the loop */
500	
501	          *pptr += ELF_ALIGNUP(shdr->sh_size);
502	#endif
503	        }
504	    }
505	
506	  /* Update GOT table */
507	
508	#ifdef CONFIG_LIBC_ELF_GOT
509	  if (loadinfo->gotindex >= 0)
510	    {
511	      FAR Elf_Shdr *gotshdr = &loadinfo->shdr[loadinfo->gotindex];
512	      FAR uintptr_t *got = (FAR uintptr_t *)gotshdr->sh_addr;
513	      FAR uintptr_t *end = got + gotshdr->sh_size / sizeof(uintptr_t);
514	
515	      for (; got < end; got++)
516	        {
517	          for (i = 0; i < loadinfo->ehdr.e_shnum; i++)
518	            {
519	              FAR Elf_Shdr *shdr = &loadinfo->shdr[i];
520	
521	              if ((shdr->sh_flags & SHF_ALLOC) == 0)
522	                {
523	                  continue;
524	                }
525	
526	              if (*got >= shdr->sh_offset &&
527	                  *got < shdr->sh_offset + shdr->sh_size)
528	                {
529	                  *got += shdr->sh_addr - shdr->sh_offset;
530	                }
531	            }
532	        }
533	    }
534	#endif
535	
536	  return OK;
537	}
