540	 * Public Functions
541	 ****************************************************************************/
542	
543	/****************************************************************************
544	 * Name: libelf_load_vma
545	 *
546	 * Description:
547	 *   Loads the binary into memory, allocating memory, performing relocations
548	 *   and initializing the data and bss segments.
549	 *
550	 * Returned Value:
551	 *   0 (OK) is returned on success and a negated errno is returned on
552	 *   failure.
553	 *
554	 ****************************************************************************/
555	
556	int libelf_load_vma(FAR struct mod_loadinfo_s *loadinfo, bool is_vma)
557	{
558	  int ret;
559	
560	  binfo("loadinfo: %p\n", loadinfo);
561	  DEBUGASSERT(loadinfo && loadinfo->filfd >= 0);
562	
563	  /* Load section and program headers into memory */
564	
565	  ret = libelf_loadhdrs(loadinfo);
566	  if (ret < 0)
567	    {
568	      berr("ERROR: libelf_loadhdrs failed: %d\n", ret);
569	      goto errout_with_buffers;
570	    }
571	
572	#ifdef CONFIG_LIBC_ELF_GOT
573	  loadinfo->gotindex = libelf_findsection(loadinfo, ".got");
574	  if (loadinfo->gotindex >= 0)
575	    {
576	      binfo("GOT section found! index %d\n", loadinfo->gotindex);
577	      if (ioctl(loadinfo->filfd, FIOC_XIPBASE,
578	                (unsigned long)&loadinfo->xipbase) >= 0)
579	        {
580	          binfo("can use xipbase %zu\n", loadinfo->xipbase);
581	        }
582	    }
583	#endif
584	
585	  /* Determine total size to allocate */
586	
587	  libelf_elfsize(loadinfo, true);
588	
589	  /* Allocate (and zero) memory for the ELF file. */
590	
591	  /* Allocate memory to hold the ELF image */
592	
593	  /* For Dynamic shared objects the relative positions between
594	   * text and data must be maintained due to references to the
595	   * GOT. Therefore we cannot do two different allocations.
596	   */
597	
598	  if (!is_vma)
599	    {
600	      if (loadinfo->ehdr.e_type == ET_REL ||
601	          loadinfo->ehdr.e_type == ET_EXEC)
602	        {
603	#  ifndef CONFIG_ARCH_USE_SEPARATED_SECTION
604	#    ifdef CONFIG_LIBC_ELF_GOT
605	          if (loadinfo->xipbase != 0)
606	            {
607	              loadinfo->textalloc = loadinfo->xipbase +
608	                                    loadinfo->shdr[1].sh_offset;
609	            }
610	          else
611	#    endif
612	          if (loadinfo->textsize > 0)
613	            {
614	#    ifdef CONFIG_ARCH_USE_TEXT_HEAP
615	              loadinfo->textalloc = (uintptr_t)
616	                                    up_textheap_memalign(loadinfo->textalign,
617	                                                         loadinfo->textsize +
618	                                                         loadinfo->segpad);
619	#    else
620	              loadinfo->textalloc = (uintptr_t)
621	                                    lib_memalign(loadinfo->textalign,
622	                                                 loadinfo->textsize +
623	                                                 loadinfo->segpad);
624	#    endif
625	              if (!loadinfo->textalloc)
626	                {
627	                  berr("ERROR: Failed to allocate memory"
628	                       "for the module text\n");
629	                  ret = -ENOMEM;
630	                  goto errout_with_buffers;
631	                }
632	            }
633	
634	          if (loadinfo->datasize > 0)
635	            {
636	#    ifdef CONFIG_ARCH_USE_DATA_HEAP
637	              loadinfo->datastart = (uintptr_t)
638	                up_dataheap_memalign(loadinfo->dataalign,
639	                                     loadinfo->datasize);
640	#    else
641	              loadinfo->datastart = (uintptr_t)
642	                lib_memalign(loadinfo->dataalign,
643	                             loadinfo->datasize);
644	#    endif
645	              if (!loadinfo->datastart)
646	                {
647	                  berr("ERROR: Failed to allocate memory"
648	                       "for the module data\n");
649	                  ret = -ENOMEM;
650	                  goto errout_with_buffers;
651	                }
652	            }
653	#  endif
654	        }
655	      else if (loadinfo->ehdr.e_type == ET_DYN)
656	        {
657	          loadinfo->textalloc = (uintptr_t)lib_memalign(loadinfo->textalign,
658	                                                        loadinfo->textsize +
659	                                                        loadinfo->datasize +
660	                                                        loadinfo->segpad);
661	
662	          if (!loadinfo->textalloc)
663	            {
664	              berr("ERROR: Failed to allocate memory for the module\n");
665	              ret = -ENOMEM;
666	              goto errout_with_buffers;
667	            }
668	
669	          loadinfo->datastart = loadinfo->textalloc +
670	                                loadinfo->textsize +
671	                                loadinfo->segpad;
672	        }
673	    }
674	
675	  /* Load ELF section data into memory */
676	
677	  ret = libelf_loadfile(loadinfo, is_vma);
678	  if (ret < 0)
679	    {
680	      berr("ERROR: libelf_loadfile failed: %d\n", ret);
681	      goto errout_with_buffers;
682	    }
683	
684	#ifdef CONFIG_LIBC_ELF_EXIDX_SECTNAME
685	  ret = libelf_findsection(loadinfo, CONFIG_LIBC_ELF_EXIDX_SECTNAME);
686	  if (ret < 0)
687	    {
688	      binfo("libelf_findsection: Exception Index section not found: %d\n",
689	            ret);
690	    }
691	  else
692	    {
693	      up_init_exidx(loadinfo->shdr[ret].sh_addr,
694	                    loadinfo->shdr[ret].sh_size);
695	    }
696	#endif
697	
698	  return OK;
699	
700	  /* Error exits */
701	
702	errout_with_buffers:
703	  libelf_unload(loadinfo);
704	  return ret;
705	}
