707	/****************************************************************************
708	 * Name: libelf_load_with_addrenv
709	 *
710	 * Description:
711	 *   Loads the binary into memory, use the address environment to load the
712	 *   binary.
713	 *
714	 * Returned Value:
715	 *   0 (OK) is returned on success and a negated errno is returned on
716	 *   failure.
717	 *
718	 ****************************************************************************/
719	
720	#ifdef CONFIG_ARCH_ADDRENV
721	int libelf_load_with_addrenv(FAR struct mod_loadinfo_s *loadinfo,
722	                             bool is_vma)
723	{
724	  int ret;
